//Set up two variables to track the current and last number
var current = 0; 
var last = 1; 

//Loop from 0 to 100
for (var i = 0; i < 100; i++) { 

  //Calculate the next Fibonacci number as the sum of the two variables 
  var temp = current + last; 

  //Print out the current number 
  console.log(current); 

  //Rebind the last number to the current number 
  last = current;  

  //Rebind the current number to the value stored in the temp variable 
  current = temp; 
}

def count_words(str): 
  counts = dict() 
  words = str.split() 

  for word in words: 
    if word in counts: 
      counts[word] += 1
    else: 
      counts[word] = 1

  return counts

def find_longest_word(str): 
  words = str.split() 
  longest_word = ""
  longest_length = 0
  for word in words: 
    word_length = len(word) 
    if word_length > longest_length:
      longest_length = word_length
      longest_word = word 

  return longest_word

